// Draw fish
function drawFish(x, y, size, color) {
    // Body
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(x, y, size, size * 0.6, 0, 0, Math.PI * 2);
    ctx.fill();

    // Tail
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x - size, y);
    ctx.lineTo(x - size * 1.5, y - size * 0.3);
    ctx.lineTo(x - size * 1.5, y + size * 0.3);
    ctx.closePath();
    ctx.fill();

    // Eye
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(x + size * 0.3, y - size * 0.2, 3, 0, Math.PI * 2);
    ctx.fill();

    // Fin
    ctx.fillStyle = '#2a6a2a';
    ctx.beginPath();
    ctx.moveTo(x - size * 0.2, y);
    ctx.lineTo(x - size * 0.8, y - size * 0.3);
    ctx.lineTo(x - size * 0.8, y + size * 0.3);
    ctx.closePath();
    ctx.fill();
}

