// Draw stack of vinyl records
const records = 8;
const baseY = 700;
const gap = 20;
const radius = 200;
const centerX = W / 2;
const centerY = baseY + records * gap / 2;

// Colors for vinyls
const colors = [
  '#2c3e50', '#34495e', '#7f8c8d', '#95a5a6',
  '#bdc3c7', '#e74c3c', '#3498db', '#9b59b6'
];

// Draw each record
for (let i = 0; i < records; i++) {
  const y = baseY - i * gap;

  // Record body
  ctx.beginPath();
  ctx.arc(centerX, y, radius, 0, Math.PI * 2);
  ctx.fillStyle = colors[i % colors.length];
  ctx.fill();

  // Record center
  ctx.beginPath();
  ctx.arc(centerX, y, 20, 0, Math.PI * 2);
  ctx.fillStyle = '#2c3e50';
  ctx.fill();

  // Grooves
  ctx.strokeStyle = '#5d4037';
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let angle = 0; angle < Math.PI * 2; angle += 0.01) {
    const x = centerX + Math.cos(angle) * (radius - 10);
    const y = centerY + Math.sin(angle) * (radius - 10);
    if (i > 0) {
      ctx.lineTo(x, y);
    } else {
      ctx.moveTo(x, y);
    }
  }
  ctx.stroke();

  // Label
  ctx.fillStyle = '#f1c40f';
  ctx.font = 'bold 16px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(`YEAR ${records - i}`, centerX, y + 15);
}

// Shadow under stack
