// Draw concentric circles
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 40;

const colors = [
  '#ffd2b4', // pastel pink
  '#c9e9ff', // pastel blue
  '#d0f4de', // pastel green
  '#fff9b7', // pastel yellow
  '#e6c5ff', // pastel purple
  '#ffb3c6'  // pastel rose
];

// Draw circles with different colors
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 30;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fillStyle = colors[i % 6];
  ctx.fill();

  // Add subtle border to each circle
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.stroke();
}

// Draw radial patterns
ctx.fillStyle = '#ffffff';
for (let angle = 0; angle < Math.PI * 2; angle += Math.PI / 8) {
  const distance = 60 + Math.random() * 40;
  const x = centerX + Math.cos(angle) * distance;
  const y = centerY + Math.sin(angle) * distance;

  // Draw smaller circles at each radial point
  ctx.beginPath();
  ctx.arc(x, y, 15 + Math.random() * 10, 0, Math.PI * 2);
  ctx.fill();

  // Add gradient effect
  const gradient = ctx.createRadialGradient(
    x, y, 0,
    x, y, 15 + Math.random() * 10
  );
  gradient.addColorStop(0, '#ffffff');
  gradient.addColorStop(1, '#f0f0f0');

  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(x, y, 15 + Math.random() * 10, 0, Math.PI * 2);
  ctx.fill();
}

// Draw center pattern
ctx.fillStyle = '#2d3436';
ctx.beginPath();
ctx.arc(centerX, centerY, 20, 0, Math.PI * 2);
ctx.fill();

// Draw inner circles
ctx.fillStyle = '#3e4441';
for (let i = 0; i < 4; i++) {
  const angle = (i * Math.PI) / 2;
  const x = centerX + Math.cos(angle) * 15;
  const y = centerY + Math.sin(angle) * 15;

  ctx.beginPath();
  ctx.arc(x, y, 8, 0, Math.PI * 2);
  ctx.fill();
}

// Draw lines connecting points
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 1;
for (let angle = 0; angle < Math.PI * 2; angle += Math.PI / 8) {
  const distance = 60 + Math.random() * 40;
  const startX = centerX + Math.cos(angle) * distance;
  const startY = centerY + Math.sin(angle) * distance;

  // Random offset to create more interesting pattern
  const offsetX = Math.random() * 10 - 5;
  const offsetY = Math.random() * 10 - 5;

  const endX = centerX + Math.cos(angle) * (distance + 20);
  const endY = centerY + Math.sin(angle) * (distance + 20);

  ctx.beginPath();
  ctx.moveTo(startX + offsetX, startY + offsetY);
  ctx.lineTo(endX + offsetX, endY + offsetY);
  ctx.stroke();
}

// Draw diagonal lines
ctx.strokeStyle = '#ffffff';
