// Draw cool tones fractal spiral
ctx.fillStyle = '#0a0a2a';
ctx.fillRect(0, 0, W, H);

const drawSpiral = (x, y, size, depth) => {
    if (depth > 0) {
        const angle = depth * 0.3;
        const nx = x + Math.cos(angle) * size;
        const ny = y + Math.sin(angle) * size;

        // Cool tones: deep blues, violets, indigos
        const hue = (depth % 5) * 30;
        const saturation = 70 + depth * 5;
        const lightness = 20 + depth * 2;
        const color = `hsl(${hue}, ${saturation}%, ${lightness}%)`;

        ctx.fillStyle = color;
        ctx.fillRect(Math.floor(nx), Math.floor(ny), 2, 2);

        // Recursive calls for spiral arms
        drawSpiral(nx, ny, size * 0.8, depth - 1);
        drawSpiral(nx + 1, ny + 1, size * 0.8, depth - 1);
        drawSpiral(nx - 1, ny - 1, size * 0.8, depth - 1);
    }
};

